for (const auto& coord : polygon_coords) {
    Kernel::Point_3 point(coord[0], coord[1], coord[2]);
    vertices.push_back(triangulation.insert_in_plane(point, plane));
}

for (std::size_t i = 0; i < vertices.size(); ++i) {
    triangulation.insert_constraint(vertices[i], vertices[(i + 1) % vertices.size()]);
}

walk_start = triangulation.locate(vertices[0]->point(), vertices[0]);

